css:
.iclsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #3a3128;
    background: linear-gradient(180deg, #fbf6ec 0%, #f4ecdd 100%);
    border-radius: 18px;
    border: 1px solid #e6dcc6;
}

.iclsim-container * {
    box-sizing: border-box;
}

.iclsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0f4c4a 0%, #14605b 55%, #1f7a6f 100%);
    color: #f7f1e3;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #0c3b39;
    box-shadow: 0 12px 30px rgba(15, 76, 74, 0.30);
}

.iclsim-header h1 {
    margin: 8px 0 10px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 2.4rem;
    font-weight: 700;
    letter-spacing: -0.3px;
    color: #fdf8ee;
}

.iclsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #f1c873;
    background: rgba(241, 200, 115, 0.14);
    border: 1px solid rgba(241, 200, 115, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.iclsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.6;
    color: #e7ddca;
}

.iclsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b5d49;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.iclsim-period-counter #currentDay,
.iclsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f4c4a;
}

.iclsim-round-name {
    background: rgba(15, 76, 74, 0.10);
    color: #0f4c4a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.iclsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5b1f;
    background: rgba(199, 120, 41, 0.14);
    border: 1px solid rgba(199, 120, 41, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.iclsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.iclsim-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e9ddc6;
    box-shadow: 0 6px 16px rgba(58, 49, 40, 0.08);
    border-top: 4px solid #1f7a6f;
}

.iclsim-card-margin { border-top-color: #1f7a6f; }
.iclsim-card-mission { border-top-color: #8a5cc4; }
.iclsim-card-nps { border-top-color: #c77829; }
.iclsim-card-enroll { border-top-color: #2c6fae; }

.iclsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7a63;
}

.iclsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2a2218;
    font-variant-numeric: tabular-nums;
}

.iclsim-card-margin .iclsim-value { color: #14605b; }
.iclsim-card-mission .iclsim-value { color: #7a4cb8; }
.iclsim-card-nps .iclsim-value { color: #b76a1f; }
.iclsim-card-enroll .iclsim-value { color: #2c6fae; }

.iclsim-sublabel {
    font-size: 0.76rem;
    color: #97876e;
    line-height: 1.35;
}

.iclsim-margin-negative .iclsim-value { color: #c0392b; }
.iclsim-margin-positive .iclsim-value { color: #14605b; }

.iclsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffdf8;
    border: 1px solid #e9ddc6;
    color: #5b4f3d;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.iclsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #14605b;
}

.iclsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #f1c873;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #e9ddc6;
    border-left: 5px solid #f1c873;
    box-shadow: 0 6px 16px rgba(58, 49, 40, 0.07);
}

.iclsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.iclsim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #0f4c4a;
    margin-bottom: 6px;
}

.iclsim-briefing-text {
    font-size: 0.96rem;
    line-height: 1.6;
    color: #4a4133;
}

.iclsim-briefing-text strong { color: #14605b; }
.iclsim-briefing-text em { color: #9a5b1f; font-style: italic; }

.iclsim-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e9ddc6;
    box-shadow: 0 6px 16px rgba(58, 49, 40, 0.07);
}

.iclsim-controls h3 {
    margin: 0 0 16px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.18rem;
    font-weight: 700;
    color: #0f4c4a;
    border-bottom: 2px solid #efe6d3;
    padding-bottom: 8px;
}

.iclsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.93rem;
    color: #4a4133;
    margin: 14px 0 6px;
}

.iclsim-container select,
.iclsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8c9aa;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #3a3128;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.iclsim-container select:focus,
.iclsim-container input[type="number"]:focus {
    outline: none;
    border-color: #1f7a6f;
    box-shadow: 0 0 0 3px rgba(31, 122, 111, 0.16);
}

.iclsim-container select option {
    background-color: #fffdf8;
    color: #3a3128;
}

.iclsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f7a6f;
}

.iclsim-range-readout,
.iclsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b5d49;
    margin-top: 4px;
}

.iclsim-range-readout span:last-child,
.iclsim-alloc-readout span:nth-child(2) {
    color: #14605b;
    font-weight: 800;
}

.iclsim-hint {
    font-size: 0.81rem;
    color: #97876e;
    margin-top: 4px;
    line-height: 1.45;
}

.iclsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.iclsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #faf4e6;
    border: 1px solid #e4d6ba;
    border-radius: 9px;
    padding: 8px 12px;
}

.iclsim-alloc-name {
    flex: 1;
    font-size: 0.87rem;
    font-weight: 600;
    color: #4a4133;
}

.iclsim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.iclsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.iclsim-container .btn-primary {
    background: linear-gradient(135deg, #0f4c4a 0%, #1f7a6f 100%);
    border: none;
    color: #fdf8ee;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(15, 76, 74, 0.32);
}

.iclsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.iclsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8c9aa;
    color: #6b5d49;
    background: transparent;
}

.iclsim-coach {
    background: linear-gradient(135deg, #14605b 0%, #0f4c4a 100%);
    color: #eef6f0;
    border: 1px solid #0c3b39;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(15, 76, 74, 0.22);
}

.iclsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f1c873;
    margin-bottom: 8px;
}

.iclsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.iclsim-coach-body strong { color: #f1c873; }
.iclsim-coach-body em { color: #ffe1a8; font-style: italic; }

.iclsim-history,
.iclsim-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e9ddc6;
    box-shadow: 0 6px 16px rgba(58, 49, 40, 0.07);
}

.iclsim-history h3,
.iclsim-chart h3 {
    margin: 0 0 14px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 1.12rem;
    font-weight: 700;
    color: #0f4c4a;
}

.iclsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a4133;
}

.iclsim-container table#usfHistoryTable th {
    background: #faf4e6;
    color: #14605b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e4d6ba;
}

.iclsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efe6d3;
    color: #5b4f3d;
}

.iclsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fbf6ec;
}

.iclsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .iclsim-container {
        padding: 14px;
    }
    .iclsim-header h1 {
        font-size: 1.8rem;
    }
    .iclsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .iclsim-value {
        font-size: 2rem;
    }
    .iclsim-clock {
        margin-left: 0;
    }
    .iclsim-period-counter {
        font-size: 0.88rem;
    }
    .iclsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .iclsim-alloc-row {
        flex-wrap: wrap;
    }
    .iclsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .iclsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion scorecard (append-only, namespaced .icl-cm-*) */
.icl-cm { margin-top: 8px; }
.icl-cm-incomplete { text-align: center; color: #6b5d49; font-size: 1rem; padding: 18px; }
.icl-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.icl-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #0f4c4a 0%, #14605b 55%, #f1c873 150%); color: #fffdf8; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(15,76,74,0.28); }
.icl-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.icl-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.icl-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f1c873; }
.icl-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fdf8ee; border: 1px solid #e4d6ba; border-radius: 14px; padding: 14px 20px; }
.icl-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #97876e; }
.icl-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; color: #0f4c4a; margin-top: 4px; line-height: 1.15; }
.icl-cm-section { margin-bottom: 16px; }
.icl-cm-section-h { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700; color: #14605b; margin-bottom: 8px; border-bottom: 1px solid #e9ddc6; padding-bottom: 4px; }
.icl-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.icl-cm-chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; font-size: 0.85rem; font-weight: 600; border: 1px solid transparent; }
.icl-cm-ok { background: #e3f2ec; color: #0f4c4a; border-color: #bfe0d1; }
.icl-cm-no { background: #f7e9e4; color: #9a5b1f; border-color: #ecc9b6; }
.icl-cm-ico { font-weight: 800; }
.icl-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.icl-cm-kpi { background: #fffdf8; border: 1px solid #e9ddc6; border-radius: 12px; padding: 12px 10px; text-align: center; }
.icl-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #14605b; line-height: 1; }
.icl-cm-kpi-lbl { font-size: 0.78rem; font-weight: 700; color: #4a4133; margin-top: 6px; }
.icl-cm-kpi-sub { font-size: 0.68rem; color: #97876e; margin-top: 2px; }
.icl-cm-insights { margin: 0; padding-left: 20px; color: #3a3128; }
.icl-cm-insights li { margin-bottom: 6px; line-height: 1.4; }
@media (max-width: 620px) { .icl-cm-kpis { grid-template-columns: repeat(2, 1fr); } }

