(function() {
    'use strict';

    class HumanistDeanAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Humanist Dean`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card — Instituto Cumbre de Liderazgo (MXN).
            this.BUDGET = 18.0;          // MXN 18M fixed design-and-delivery envelope
            this.MARGIN_TARGET = 6.0;    // MXN 6M first-cohort margin mandate
            this.TARGET_TUITION = 95000; // MX$95,000 premium open-enrollment price
            this.BREAKEVEN = 190;        // ~MXN 18M ÷ MX$95K
            this.MARGIN_ENROLL = 253;    // ~(18M + 6M) ÷ MX$95K
            this.CAP = 320;              // single-cohort room & faculty cap
            this.COACH_RATE = 2200;      // MX$/hour certified executive coach
            this.CONTENT_RATE = 1400;    // MX$/hour adjunct content faculty
            this.COMPETITOR_PRICE = 70000; // cheaper online provider reference

            // Concept truths (the defensible answers).
            this.TRUE_PHILOSOPHY = `reinforce`;
            this.TRUE_TENSION = `coaching`;
            this.TRUE_FRAMING = `hybrid`;   // humanistic is also strong; hybrid is the balanced ideal
            this.TRUE_RATIO = `balanced`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    margin: 0,        // MXN M first-cohort contribution vs the 18M budget
                    mission: 40,      // dignity & values-alignment score (0-100)
                    nps: 30,          // projected transformational experience (0-100)
                    enrollment: 0,    // forecast participants
                    budgetUsed: 0,    // MXN M of the 18M envelope allocated
                    coachingOverrun: false,
                    incoherent: false,
                    facultyWalkout: false,
                    marginHistory: [0],
                    missionHistory: [40],
                    npsHistory: [30],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix so a
                // blind click-through cannot auto-win.
                state.decisions = {
                    philosophy: `reinforce`,
                    tension: `coaching`,
                    faculty: 50,
                    framing: `humanistic`,
                    price: 95000,
                    cohort: 220,
                    content: 6,
                    coaching: 4,
                    experiential: 3,
                    marketing: 3,
                    services: 2,
                    ratio: `high`,
                    board: `promise`,
                    defenceFaculty: `reassure`,
                    coherence: `partial`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ph = document.getElementById(`philosophyInput`);
                const tn = document.getElementById(`tensionInput`);
                const fc = document.getElementById(`facultyInput`);
                if (ph) decisions.philosophy = ph.value;
                if (tn) decisions.tension = tn.value;
                if (fc) decisions.faculty = parseInt(fc.value, 10);
                if (!Number.isFinite(decisions.faculty) || decisions.faculty < 0 || decisions.faculty > 100) {
                    warn(`warn_faculty_range`); return false;
                }
            } else if (round === 2) {
                const fr = document.getElementById(`framingInput`);
                const pr = document.getElementById(`priceInput`);
                const co = document.getElementById(`cohortInput`);
                if (fr) decisions.framing = fr.value;
                if (pr) decisions.price = parseFloat(pr.value);
                if (co) decisions.cohort = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.price) || decisions.price < 50000 || decisions.price > 140000) {
                    warn(`warn_price_range`); return false;
                }
                if (!Number.isFinite(decisions.cohort) || decisions.cohort < 0 || decisions.cohort > this.CAP) {
                    warn(`warn_cohort_range`); return false;
                }
            } else if (round === 3) {
                const ids = [`contentInput`, `coachingInput`, `experientialInput`, `marketingInput`, `servicesInput`];
                const keys = [`content`, `coaching`, `experiential`, `marketing`, `services`];
                for (let i = 0; i < ids.length; i++) {
                    const el = document.getElementById(ids[i]);
                    if (el) decisions[keys[i]] = parseFloat(el.value);
                }
                const rt = document.getElementById(`ratioInput`);
                if (rt) decisions.ratio = rt.value;
                const parts = keys.map((k) => decisions[k]);
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(parts.reduce((a, b) => a + b, 0) * 10) / 10;
                if (Math.abs(total - this.BUDGET) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const bd = document.getElementById(`boardInput`);
                const df = document.getElementById(`defenceFacultyInput`);
                const ch = document.getElementById(`coherenceInput`);
                const cv = document.getElementById(`convictionInput`);
                if (bd) decisions.board = bd.value;
                if (df) decisions.defenceFaculty = df.value;
                if (ch) decisions.coherence = ch.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite (previously computed only inside getPerformanceSummary and discarded).
            const margin = ds.margin;
            const mission = Math.round(ds.mission);
            const nps = Math.round(ds.nps);
            const enrollment = Math.round(ds.enrollment);
            const marginScore = Math.max(0, Math.min(100, ((margin + 4) / 10) * 100));
            return Math.round(
                marginScore * 0.30 + mission * 0.34 + nps * 0.26 + Math.min(100, (enrollment / this.MARGIN_ENROLL) * 100) * 0.10
            );
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let marginDelta = 0, missionDelta = 0, npsDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the mission-margin tension and set a design philosophy.
                switch (d.philosophy) {
                    case `reinforce`: missionDelta += 10; npsDelta += 4; coachKey = `coach_r1_reinforce`; break;
                    case `balance`: missionDelta += 4; npsDelta += 2; coachKey = `coach_r1_balance`; break;
                    case `margin`: missionDelta -= 8; npsDelta -= 4; coachKey = `coach_r1_margin`; break;
                    case `mission`: missionDelta += 8; npsDelta += 6; marginDelta -= 1; coachKey = `coach_r1_mission`; break;
                }

                // Name where mission & margin genuinely conflict (the coaching ratio).
                switch (d.tension) {
                    case `coaching`: missionDelta += 6; npsDelta += 4; if (d.philosophy === `reinforce`) coachKey = `coach_r1_sharp`; break;
                    case `volume`: missionDelta -= 6; npsDelta -= 4; coachKey = `coach_r1_volume`; break;
                    case `price`: marginDelta -= 1; missionDelta += 1; coachKey = `coach_r1_price`; break;
                    case `none`: missionDelta -= 6; npsDelta -= 2; coachKey = `coach_r1_naive`; break;
                }

                // Treat the senior faculty as a real stakeholder (Common Error 5 foreshadow).
                if (d.faculty >= 65) { missionDelta += 6; npsDelta += 3; }
                else if (d.faculty <= 25) { missionDelta -= 6; coachKey = `coach_r1_lowfaculty`; }

                summaryKey = (d.philosophy === `reinforce` && d.tension === `coaching`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose framing, price and cohort — the revenue & enrollment engine.
                // Demand model: each framing supports a realistic enrollment at a given price,
                // anchored on the MX$95K target. Over-pricing thins the room; under-pricing fills
                // it but cannot clear the margin.
                const priceRatio = d.price / this.TARGET_TUITION;   // 1.0 at target
                let baseDemand, priceSensitivity, wtpPremiumOk;
                if (d.framing === `humanistic`) {
                    // Smaller, mission-aligned, higher willingness-to-pay audience.
                    baseDemand = 235; priceSensitivity = 90; wtpPremiumOk = 1.20;
                } else if (d.framing === `roi`) {
                    // Bigger volume but commoditised against the MX$70K online competitor.
                    baseDemand = 300; priceSensitivity = 240; wtpPremiumOk = 1.0;
                } else { // hybrid
                    baseDemand = 270; priceSensitivity = 140; wtpPremiumOk = 1.12;
                }
                // Realistic enrollment the framing supports at this price (capped at room).
                let realEnroll = baseDemand - priceSensitivity * (priceRatio - 0.85);
                realEnroll = Math.max(0, Math.min(this.CAP, Math.round(realEnroll)));
                // The team's stated cohort target is honoured only up to what demand supports.
                const forecast = Math.min(d.cohort, realEnroll);
                ds.enrollment = forecast;

                // Revenue (MXN M) = price × enrollment. Provisional margin = revenue − 18M budget.
                const revenueM = (d.price * forecast) / 1000000;
                marginDelta += revenueM - this.BUDGET;   // budget is the fixed envelope

                // Framing's effect on mission & pricing power.
                if (d.framing === `humanistic`) { missionDelta += 10; npsDelta += 6; }
                else if (d.framing === `hybrid`) { missionDelta += 5; npsDelta += 3; }
                else { missionDelta -= 12; npsDelta -= 8; }   // ROI commoditises the mission

                // Value-based pricing: a premium is rewarded ONLY under a purpose framing;
                // pricing near/below the online competitor under ROI is the commodity trap.
                if (d.framing !== `roi` && d.price >= this.TARGET_TUITION && d.price <= this.TARGET_TUITION * wtpPremiumOk) {
                    missionDelta += 3; coachKey = `coach_r2_valuepricing`;
                } else if (d.price <= this.COMPETITOR_PRICE + 5000) {
                    npsDelta -= 3; coachKey = `coach_r2_underprice`;
                } else if (d.price > this.TARGET_TUITION * wtpPremiumOk) {
                    coachKey = `coach_r2_overprice`;   // priced past willingness-to-pay, thins the room
                }

                if (coachKey === `coach_default`) {
                    if (d.framing === `roi`) coachKey = `coach_r2_roi`;
                    else if (d.framing === `humanistic`) coachKey = `coach_r2_humanistic`;
                    else coachKey = `coach_r2_hybrid`;
                }

                summaryKey = (forecast >= this.MARGIN_ENROLL && d.framing !== `roi`) ? `sum_r2_good` :
                             (d.framing === `roi` ? `sum_r2_roi` :
                             (forecast < this.BREAKEVEN ? `sum_r2_short` : `sum_r2_weak`));
            } else if (round === 3) {
                // Allocate the MXN 18M and set the coaching-to-content ratio.
                const coaching = d.coaching, content = d.content, experiential = d.experiential;
                const marketing = d.marketing, services = d.services;
                spend = this.BUDGET;   // the whole envelope is committed this round

                // Coaching is the humanistic core but the costliest line (Common Error 3).
                missionDelta += coaching * 5 + experiential * 4 + services * 1.5 - content * 0.5;
                npsDelta += coaching * 4 + experiential * 3.5 + services * 1;

                // Marketing converts to enrollment up to what the framing/price supported.
                if (marketing >= 3) {
                    const lift = Math.min(40, Math.round((marketing - 2) * 12));
                    const newEnroll = Math.min(this.CAP, ds.enrollment + lift);
                    const added = newEnroll - ds.enrollment;
                    ds.enrollment = newEnroll;
                    marginDelta += (d.price * added) / 1000000;   // extra heads add contribution
                } else if (marketing < 2) {
                    // Starved marketing loses some of the forecast cohort.
                    const lost = Math.round(ds.enrollment * 0.12);
                    ds.enrollment = Math.max(0, ds.enrollment - lost);
                    marginDelta -= (d.price * lost) / 1000000;
                    coachKey = `coach_r3_nomarketing`;
                }

                // Coaching-to-content ratio: the costed humanistic lever.
                switch (d.ratio) {
                    case `high`:
                        missionDelta += 8; npsDelta += 8;
                        // Uncosted coaching ambition blows up the P&L (the MX$11M-for-coaching warning).
                        if (coaching < 6) { marginDelta -= 3.5; ds.coachingOverrun = true; coachKey = `coach_r3_overrun`; }
                        else { marginDelta -= 1.5; coachKey = `coach_r3_highcosted`; }
                        break;
                    case `balanced`:
                        missionDelta += 5; npsDelta += 5; marginDelta += 1;
                        if (coachKey === `coach_default`) coachKey = `coach_r3_balanced`;
                        break;
                    case `low`:
                        missionDelta -= 8; npsDelta -= 8; marginDelta += 1.5;
                        ds.incoherent = true; coachKey = `coach_r3_lowcoaching`;
                        break;
                }

                summaryKey = (d.ratio === `balanced` && coaching >= 4 && marketing >= 2) ? `sum_r3_good` :
                             (d.ratio === `low` ? `sum_r3_low` :
                             (ds.coachingOverrun ? `sum_r3_overrun` : `sum_r3_weak`));
            } else if (round === 4) {
                // Defend the program to the board AND the mission-guardian faculty.
                switch (d.board) {
                    case `evidence`: marginDelta += 1; missionDelta += 2; coachKey = `coach_r4_board_evidence`; break;
                    case `promise`: npsDelta -= 2; coachKey = `coach_r4_board_promise`; break;
                    case `dodge`: marginDelta -= 1; coachKey = `coach_r4_board_dodge`; break;
                }

                switch (d.defenceFaculty) {
                    case `codesign`: missionDelta += 12; npsDelta += 8; coachKey = `coach_r4_faculty_codesign`; break;
                    case `reassure`: missionDelta -= 2; coachKey = `coach_r4_faculty_reassure`; break;
                    case `ignore`:
                        missionDelta -= 14; npsDelta -= 10; ds.facultyWalkout = true;
                        coachKey = `coach_r4_faculty_walkout`; break;
                }

                // Coherence between what the framing SAYS and what the design DOES (Common Error 4).
                switch (d.coherence) {
                    case `aligned`: missionDelta += 8; npsDelta += 6; if (d.defenceFaculty === `codesign`) coachKey = `coach_r4_coherent`; break;
                    case `partial`: missionDelta -= 2; npsDelta -= 2; break;
                    case `veneer`: missionDelta -= 12; npsDelta -= 8; ds.incoherent = true; coachKey = `coach_r4_veneer`; break;
                }

                if (d.conviction >= 60) { missionDelta += 4; }
                else if (d.conviction <= 25) { missionDelta -= 4; }

                summaryKey = (d.defenceFaculty === `codesign` && d.coherence === `aligned` && d.board === `evidence`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: the 18M envelope is committed in Round 3.
            ds.budgetUsed = Math.min(this.BUDGET, Math.round((ds.budgetUsed + spend) * 10) / 10);

            // Apply deltas, clamped (mission & NPS 0-100; margin is signed MXN M).
            ds.margin = Math.round((ds.margin + marginDelta) * 10) / 10;
            ds.mission = Math.max(0, Math.min(100, Math.round(ds.mission + missionDelta)));
            ds.nps = Math.max(0, Math.min(100, Math.round(ds.nps + npsDelta)));

            ds.marginHistory.push(ds.margin);
            ds.missionHistory.push(ds.mission);
            ds.npsHistory.push(ds.nps);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 - persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                margin: ds.margin,
                marginDelta: Math.round(marginDelta * 10) / 10,
                mission: ds.mission,
                missionDelta: Math.round(missionDelta),
                nps: ds.nps,
                npsDelta: Math.round(npsDelta),
                enrollment: ds.enrollment,
                budgetUsed: ds.budgetUsed,
                coachingOverrun: ds.coachingOverrun,
                facultyWalkout: ds.facultyWalkout,
                incoherent: ds.incoherent,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // MXN, disambiguated as MX$. English "MX$6.0M"; Spanish "6,0 MMX$" (comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M MX$`;
            }
            return `${sign}MX$${abs.toFixed(1)}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const card = document.querySelector(`.iclsim-card-margin`);
                if (card) {
                    card.classList.toggle(`iclsim-margin-positive`, Number(v) >= self.MARGIN_TARGET - 0.05);
                    card.classList.toggle(`iclsim-margin-negative`, Number(v) < -0.05);
                }
                return self._fmtMoney(Number(v));
            });
            uiManager.bind(`missionDisplay`, `domainState.mission`, (v) => Math.round(Number(v)));
            uiManager.bind(`npsDisplay`, `domainState.nps`, (v) => Math.round(Number(v)));
            uiManager.bind(`enrollDisplay`, `domainState.enrollment`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.BUDGET);
            });

            // Faculty-weight slider readout.
            const fc = document.getElementById(`facultyInput`);
            const fcReadout = document.getElementById(`facultyReadout`);
            if (fc && fcReadout) {
                fcReadout.textContent = fc.value;
                fc.addEventListener(`input`, function() { fcReadout.textContent = fc.value; });
            }

            // Budget live total (must hit MXN 18.0M).
            const allocIds = [`contentInput`, `coachingInput`, `experientialInput`, `marketingInput`, `servicesInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.iclsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.BUDGET) > 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        getChartConfig() {
            return {
