                                borderColor: `#8a5cc4`,
                                backgroundColor: `rgba(138,92,196,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#8a5cc4`,
