        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.missionHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                iclChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.missionHistory },
                        { data: ds.npsHistory },
                        { data: ds.marginHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const margin = ds.margin;
            const mission = Math.round(ds.mission);
            const nps = Math.round(ds.nps);
            const enrollment = Math.round(ds.enrollment);

            // Composite: hitting the margin target, mission fidelity, NPS — plus an enrollment
            // sanity check. Margin normalised so MX$6M ≈ full marks, losses penalised.
            // v1.1.0 - reuse the shared helper so the completion composite == final period's persisted score.
            const composite = this._composite(ds);

            const solvent = margin >= this.MARGIN_TARGET;
            const breakeven = margin >= 0;
            const humanistic = mission >= 60 && nps >= 55;
            const commercialised = ds.facultyWalkout || mission <= 35;
            const idealistic = !breakeven && mission >= 60;
            const overrun = ds.coachingOverrun;
            const incoherent = ds.incoherent;

            // v1.1.0 - tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_unsolved`;
            if (solvent && humanistic && !incoherent && composite >= 75) tierKey = `grade_viable`;
            else if (solvent && mission >= 55) tierKey = `grade_marginheld`;
            else if (commercialised) tierKey = `grade_commercialised`;
            else if (idealistic) tierKey = `grade_idealism`;
            else if (overrun && !breakeven) tierKey = `grade_overrun`;
            else if (incoherent) tierKey = `grade_incoherent`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (solvent && humanistic && !incoherent) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (commercialised) insights.push(window.mySimulation.t(`insight_commercialised`));
            else if (idealistic) insights.push(window.mySimulation.t(`insight_idealistic`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (margin < 0) insights.push(window.mySimulation.t(`insight_margin_loss`));
            else if (margin >= this.MARGIN_TARGET) insights.push(window.mySimulation.t(`insight_margin_hit`));
            if (overrun) insights.push(window.mySimulation.t(`insight_overrun`));
            if (ds.facultyWalkout) insights.push(window.mySimulation.t(`insight_walkout`));
            if (incoherent) insights.push(window.mySimulation.t(`insight_incoherent`));
            if (enrollment < this.BREAKEVEN) insights.push(window.mySimulation.t(`insight_underenrolled`));
            if (humanistic && solvent) insights.push(window.mySimulation.t(`insight_valuepricing`));

            return {
                margin: margin,
                mission: mission,
                nps: nps,
                enrollment: enrollment,
                solvent: solvent,
                breakeven: breakeven,
                humanistic: humanistic,
                commercialised: commercialised,
                missionOk: mission >= 60,
                npsOk: nps >= 55,
                enrollOk: enrollment >= this.BREAKEVEN,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="icl-cm"><p class="icl-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const self = this;
            const chip = (ok, label) => `<span class="icl-cm-chip ` + (ok ? `icl-cm-ok` : `icl-cm-no`) + `">` +
                `<span class="icl-cm-ico">` + (ok ? `✓` : `✗`) + `</span>` + label + ` · ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="icl-cm-kpi"><div class="icl-cm-kpi-val">` + val +
                `</div><div class="icl-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="icl-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="icl-cm">` +
  `<div class="icl-cm-head">` +
    `<div class="icl-cm-score"><div class="icl-cm-score-num">` + Math.round(s.composite) +
       `<span class="icl-cm-score-den">/100</span></div>` +
       `<div class="icl-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="icl-cm-verdict"><div class="icl-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="icl-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="icl-cm-section"><div class="icl-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="icl-cm-chips">` + chip(!!s.solvent, t(`cm_t_solvent`)) + chip(!!s.missionOk, t(`cm_t_mission`)) +
      chip(!!s.npsOk, t(`cm_t_nps`)) + chip(!!s.enrollOk, t(`cm_t_enroll`)) + `</div></div>` +
  `<div class="icl-cm-section"><div class="icl-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="icl-cm-kpis">` +
      kpi(t(`cm_lbl_margin`), self._fmtMoney(s.margin), t(`cm_sub_margin`)) +
      kpi(t(`cm_lbl_mission`), Math.round(s.mission), t(`cm_sub_mission`)) +
      kpi(t(`cm_lbl_nps`), Math.round(s.nps), t(`cm_sub_nps`)) +
      kpi(t(`cm_lbl_enroll`), Math.round(s.enrollment), t(`cm_sub_enroll`)) +
    `</div></div>` +
  (insights ? `<div class="icl-cm-section"><div class="icl-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="icl-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.facultyWalkout) return window.mySimulation.t(`hint_walkout`);
            if (ds.coachingOverrun) return window.mySimulation.t(`hint_overrun`);
            if (ds.incoherent) return window.mySimulation.t(`hint_incoherent`);
            if (ds.margin < 0 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_margin`);
            if (state.currentPeriod >= 2 && ds.enrollment < this.BREAKEVEN) return window.mySimulation.t(`hint_enroll`);
            if (ds.mission >= 60 && ds.nps >= 55 && ds.margin >= this.MARGIN_TARGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.margin`, label: `Margin`, i18nKey: `col_margin`, formatter: (v) => self._fmtMoney(Number(v)) },
                { key: `results.mission`, label: `Mission`, i18nKey: `col_mission`, formatter: (v) => Math.round(v) },
                { key: `results.nps`, label: `NPS`, i18nKey: `col_nps`, formatter: (v) => Math.round(v) },
                { key: `results.enrollment`, label: `Enrolled`, i18nKey: `col_enroll`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

