            return {
                en: {
                    grade_viable:           `Viable & Authentically Humanistic`,
                    grade_marginheld:       `Margin Held, Mission Intact`,
                    grade_commercialised:   `Differentiation Commercialised Away`,
                    grade_idealism:         `Idealism Without Viability`,
                    grade_overrun:          `Coaching Ambition Blew the P&L`,
                    grade_incoherent:       `Framing–Design Incoherence`,
                    grade_mixed:            `Mixed Outcome`,
                    grade_unsolved:         `Mission–Margin Unsolved`,
                    cm_score:               `Composite Score`,
                    cm_verdict:             `Verdict`,
                    cm_targets:             `Targets Met`,
                    cm_kpis:                `Mission–Margin Scorecard`,
                    cm_insights:            `What Drove This`,
                    cm_met:                 `met`,
                    cm_missed:              `missed`,
                    cm_incomplete:          `Finish all four rounds to see your mission–margin debrief.`,
                    cm_t_solvent:           `Margin ≥ MX$6M`,
                    cm_t_mission:           `Mission ≥ 60`,
                    cm_t_nps:               `NPS ≥ 55`,
                    cm_t_enroll:            `Enrolled ≥ 190`,
                    cm_lbl_margin:          `Margin`,
                    cm_lbl_mission:         `Mission`,
                    cm_lbl_nps:             `NPS`,
